begin;set search_path to public,extensions;select plan(19);
insert into auth.users(id,email) values('60000000-0000-4000-8000-000000000001','claimant-sql@example.test'),('60000000-0000-4000-8000-000000000002','tenant-sql@example.test'),('60000000-0000-4000-8000-000000000003','claim-admin-sql@example.test');
insert into private.administrator_grants(user_id,reason) values('60000000-0000-4000-8000-000000000003','Synthetic transaction administrator');
insert into private.documents(id,owner_id,object_path) values('61000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','claim/61000000-0000-4000-8000-000000000001.jpg');
insert into private.claims(id,user_id,property_id,document_id) values('62000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001');
set local role authenticated;select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000002',true);
select create_review('{"property":"20000000-0000-4000-8000-000000000001","start":"2024-01-01","end":"2024-12-01","current":false,"paid":15000,"propertyRating":4,"managerRating":2,"body":"Fictional SQL tenant review remains unchanged.","synthetic":true}');
reset role;create temporary table claim_review as select id from public.reviews where body='Fictional SQL tenant review remains unchanged.';grant select on claim_review to authenticated,anon;
set local role anon;select throws_ok($$select get_my_claims()$$,'42501',null,'Anonymous claims denied');
set local role authenticated;select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select throws_ok($$select update_claimed_details('62000000-0000-4000-8000-000000000001','{}')$$,'42501',null,'Pending cannot update');
select throws_ok($$select upsert_claimant_reply('62000000-0000-4000-8000-000000000001',(select id from claim_review),'Fictional pending reply denied')$$,'42501',null,'Pending cannot reply');
select throws_ok($$select decide_claim('62000000-0000-4000-8000-000000000001','approved','Fictional self approval denied')$$,'42501',null,'Self approval denied');
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000003',true);
select lives_ok($$select decide_claim('62000000-0000-4000-8000-000000000001','approved','Fictional administrator approval')$$,'Trusted approval');
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select throws_ok($$select create_review('{"property":"20000000-0000-4000-8000-000000000001","start":"2025-01-01","current":true,"paid":1000,"propertyRating":5,"body":"Fictional self review blocked.","synthetic":true}')$$,'42501',null,'Approved claimant cannot self review');
select throws_ok($$select update_claimed_details('62000000-0000-4000-8000-000000000001','{"name":"Fictional allowed name","description":"Demo","min":18000,"max":26000,"reason":"Fictional detail reason","status":"hidden"}')$$,'P0001',null,'Injected status denied');
select lives_ok($$select update_claimed_details('62000000-0000-4000-8000-000000000001','{"name":"Demo Neem Courtyard Updated","description":"Fictional updated description","min":18000,"max":26000,"reason":"Fictional detail update audit"}')$$,'Allowlisted details update');
select lives_ok($$select upsert_claimant_reply('62000000-0000-4000-8000-000000000001',(select id from claim_review),'Fictional property representative reply.')$$,'Approved matching reply');
select throws_ok($$select edit_review((select id from claim_review),'{}')$$,'42501',null,'Claimant cannot edit tenant review');
select throws_ok($$select delete_review((select id from claim_review))$$,'42501',null,'Claimant cannot delete tenant review');
select throws_ok($$select claim_id from public.replies$$,'42501',null,'Private claim link not exposed');
select throws_ok($$select * from private.claims$$,'42501',null,'Direct private claims denied');
set local role anon;select is((select count(*)::int from get_claimant_replies((select id from claim_review))),1,'Public representative reply visible');
select is((select body from get_review_feed('20000000-0000-4000-8000-000000000001') where id=(select id from claim_review)),'Fictional SQL tenant review remains unchanged.','Tenant text unchanged');
set local role authenticated;select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000003',true);
select lives_ok($$select decide_claim('62000000-0000-4000-8000-000000000001','revoked','Fictional representative revocation')$$,'Revoke claim');
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select throws_ok($$select upsert_claimant_reply('62000000-0000-4000-8000-000000000001',(select id from claim_review),'Fictional revoked reply denied')$$,'42501',null,'Revoked cannot reply');
select throws_ok($$select update_claimed_details('62000000-0000-4000-8000-000000000001','{}')$$,'42501',null,'Revoked cannot update');
set local role anon;select is((select count(*)::int from get_claimant_replies((select id from claim_review))),0,'Revoked representative replies hidden');
select * from finish();rollback;
